
(function ensureGame2Modal() {
  function inject() {
    if (document.getElementById('games-2-player-modal')) return;
    var modal = document.createElement('div');
    modal.id = 'games-2-player-modal';
    modal.style.cssText = 'display: none; position: fixed; inset: 0; z-index: 100000; background: #000; flex-direction: column;';
    modal.innerHTML = '<div style="background: rgba(15, 23, 42, 0.95); border-bottom: 1px solid rgba(255, 255, 255, 0.15); padding: 8px 16px; display: flex; align-items: center; justify-content: space-between; z-index: 10;"><div style="display: flex; align-items: center; gap: 12px;"><button onclick="window.closeGames2Portal()" style="background: #334155; color: #fff; border: 1px solid #475569; padding: 6px 14px; border-radius: 8px; font-size: 12px; font-weight: 800; cursor: pointer; display: flex; align-items: center; gap: 6px;">← Quay lại Kho Trò Chơi</button><span style="font-size: 14px; font-weight: 800; color: #fde047;">🎮 Kho 24 Trò Chơi Tương Tác (MHEdu)</span></div><div style="display: flex; align-items: center; gap: 8px;"><button onclick="window.closeGames2Portal()" style="background: #ef4444; color: #fff; border: none; width: 32px; height: 32px; border-radius: 8px; font-size: 14px; font-weight: 900; cursor: pointer;">✕</button></div></div><iframe id="gvdm-game-iframe" src="about:blank" style="flex: 1; width: 100%; border: none; background: #0f172a;" allow="camera; microphone; fullscreen; autoplay"></iframe>';
    document.body.appendChild(modal);
  }
  if (document.body) { inject(); } else { document.addEventListener('DOMContentLoaded', inject); }
  setInterval(inject, 800);
})();


// Đảm bảo window.openGames2Portal luôn sẵn sàng và mở modal Games 2 Runner Dashboard
if (typeof window !== 'undefined') {
  window.openGames2Portal = function() {
    if (typeof window.closeEyPortal === 'function') window.closeEyPortal();
    if (typeof window.closeHocToanPortal === 'function') window.closeHocToanPortal();
    if (typeof window.closeHocToan2Portal === 'function') window.closeHocToan2Portal();
    var playerModal = document.getElementById('games-2-player-modal');
    var iframe = document.getElementById('gvdm-game-iframe');
    if (playerModal && iframe) {
      if (!iframe.src || iframe.src === 'about:blank' || iframe.src.indexOf('/games_2/runner.html') === -1) {
        iframe.src = '/games_2/runner.html?game=/dashboard';
      }
      playerModal.style.display = 'flex';
      playerModal.style.zIndex = '999999';
      document.body.style.overflow = 'hidden';
    } else {
      window.location.href = '/games_2/runner.html?game=/dashboard';
    }
  };
  window.closeGames2Portal = function() {
    var playerModal = document.getElementById('games-2-player-modal');
    var iframe = document.getElementById('gvdm-game-iframe');
    if (iframe) iframe.src = 'about:blank';
    if (playerModal) {
      playerModal.style.display = 'none';
    }
    document.body.style.overflow = '';
  };
}

