function parseQuestionsOffline(text, images = []) {
  if (!text || !text.trim()) return SAMPLE_MATH_QUESTIONS;

  const cleanRawText = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

  // 1. Phân tích Bảng đáp án ở cuối đề thi (nếu có)
  const answerKeyMap = { part1: {}, part2: {}, part3: {} };
  const keyTableMatch = cleanRawText.match(/(?:BẢNG\s*ĐÁP\s*ÁN|ĐÁP\s*ÁN|HƯỚNG\s*DẪN\s*CHẤM)[\s\S]*$/i);
  if (keyTableMatch) {
    const keyText = keyTableMatch[0];
    const p1Matches = keyText.matchAll(/(?:Câu\s*)?(\d+)\s*[\.\:\-\/]?\s*([A-D])\b/gi);
    for (const m of p1Matches) {
      answerKeyMap.part1[parseInt(m[1])] = m[2].toUpperCase();
    }
    const p2Matches = keyText.matchAll(/(?:Câu\s*)?(\d+)\s*[\.\:\-\/]?\s*([a-d])[\)\.\:\-]\s*([ĐS]|Đúng|Sai)/gi);
    for (const m of p2Matches) {
      const qNum = parseInt(m[1]);
      const sub = m[2].toLowerCase();
      const val = /đ/i.test(m[3]) ? 'Đúng' : 'Sai';
      if (!answerKeyMap.part2[qNum]) answerKeyMap.part2[qNum] = {};
      answerKeyMap.part2[qNum][sub] = val;
    }
    const p3Matches = keyText.matchAll(/(?:Câu\s*)?(\d+)\s*[\.\:\-\=]\s*([−\-]?[0-9]+(?:[\.,][0-9]+)?)/gi);
    for (const m of p3Matches) {
      answerKeyMap.part3[parseInt(m[1])] = m[2].replace(',', '.');
    }
  }

  // 2. Nhận diện các PHẦN theo chuẩn đề Bộ GD&ĐT 2025 (Azota, iexam.vn)
  const sectionSplitRegex = /(?:^|\n)(?:PHẦN|Phần)\s*(I{1,3}|[123]|Một|Hai|Ba)[\s.:\-–]+([^\n]*)/gi;
  let secMatches = [...cleanRawText.matchAll(sectionSplitRegex)];

  let sections = [];
  if (secMatches.length >= 2) {
    for (let i = 0; i < secMatches.length; i++) {
      const start = secMatches[i].index;
      const end = (i + 1 < secMatches.length) ? secMatches[i + 1].index : cleanRawText.length;
      const numStr = secMatches[i][1].toUpperCase();
      const title = secMatches[i][2].toLowerCase();
      let type = 'MC';
      if (numStr === 'II' || numStr === '2' || numStr === 'HAI' || title.includes('đúng') || title.includes('sai')) {
        type = 'TF';
      } else if (numStr === 'III' || numStr === '3' || numStr === 'BA' || title.includes('ngắn') || title.includes('tự luận')) {
        type = 'SHORT';
      } else {
        type = 'MC';
      }
      sections.push({
        type,
        header: secMatches[i][0].trim(),
        content: cleanRawText.slice(start, end)
      });
    }
  } else {
    sections.push({ type: 'AUTO', header: '', content: cleanRawText });
  }

  const allQuestions = [];
  let globalId = 1;

  sections.forEach(sec => {
    const qSplitRegex = /(?:^|\n)(?:Câu|Bài|Question)\s*(\d+)[\s.:\-–]/gi;
    let qMatches = [...sec.content.matchAll(qSplitRegex)];
    let blocks = [];
    if (qMatches.length >= 1) {
      for (let i = 0; i < qMatches.length; i++) {
        const start = qMatches[i].index;
        const end = (i + 1 < qMatches.length) ? qMatches[i + 1].index : sec.content.length;
        blocks.push({
          num: parseInt(qMatches[i][1]),
          text: sec.content.slice(start, end).trim()
        });
      }
    } else {
      const altSplitRegex = /(?:^|\n)(\d+)[\s.:\-–]/g;
      let altMatches = [...sec.content.matchAll(altSplitRegex)];
      if (altMatches.length >= 2) {
        for (let i = 0; i < altMatches.length; i++) {
          const start = altMatches[i].index;
          const end = (i + 1 < altMatches.length) ? altMatches[i + 1].index : sec.content.length;
          blocks.push({
            num: parseInt(altMatches[i][1]),
            text: sec.content.slice(start, end).trim()
          });
        }
      } else {
        const rawBlocks = sec.content.split(/\n{2,}/).map(b => b.trim()).filter(b => b.length > 10);
        rawBlocks.forEach((rb, idx) => blocks.push({ num: idx + 1, text: rb }));
      }
    }

    blocks.forEach(blockObj => {
      let block = blockObj.text;
      const qNum = blockObj.num;

      // 1. Nhận diện hình ảnh đính kèm
      let imgUrl = null;
      const imgMatch = block.match(/!\[([^\]]*)\]\(([^)]+)\)/);
      if (imgMatch) {
        imgUrl = imgMatch[2];
        block = block.replace(imgMatch[0], '');
      } else {
        const hMatch = block.match(/\[Hình\s*(\d+)\]/i);
        if (hMatch && images && images.length > 0) {
          const hIdx = parseInt(hMatch[1], 10) - 1;
          if (hIdx >= 0 && hIdx < images.length) {
            imgUrl = images[hIdx];
            block = block.replace(hMatch[0], '');
          }
        }
      }

      // 2. Nhận diện Lời giải / Hướng dẫn giải
      let explanation = '';
      const expMatch = block.match(/(?:Lời giải|Hướng dẫn giải|Giải thích|Giải|HD)[\s.:\-–]+([\s\S]*?)$/i);
      if (expMatch) {
        explanation = expMatch[1].trim();
        block = block.slice(0, expMatch.index).trim();
      }

      // 3. Xác định dạng câu hỏi
      let blockType = sec.type;
      if (blockType === 'AUTO') {
        if (/(?:^|\n)\s*[a-d]\s*[\)\.]/i.test(block) && /đúng|sai/i.test(block + ' ' + explanation)) {
          blockType = 'TF';
        } else if (/(?:^|\n|[\.;\$\)\]\}]\s+)\s*(\*?\s*[A-D]\s*[\.\)\:\-–])/i.test(block)) {
          blockType = 'MC';
        } else if (/trả lời\s*[\:\.]/i.test(block)) {
          blockType = 'SHORT';
        } else {
          blockType = 'MC';
        }
      }

      // === DẠNG 1: PHẦN II (Trắc nghiệm Đúng - Sai chuẩn BGD / Azota) ===
      if (blockType === 'TF') {
        const cleanStem = block.replace(/^(?:Câu|Bài|Question)\s*\d+[\s.:\-–]*/i, '');
        // Tìm các ý a), b), c), d)
        const subStmtRegex = /(?:^|[\n\r\t]|\s{2,}|(?<=[\.\;\$\)\]\}])\s+|\b)\s*(\*?\s*([a-d])\s*[\)\.]\s*\*?)(?=\s|\$|<|\[|[\w(]|$)/gi;
        const subMatches = [];
        let sm;
        while ((sm = subStmtRegex.exec(cleanStem)) !== null) {
          const letter = sm[2].toLowerCase();
          const marker = sm[1];
          const markerIndex = sm.index + sm[0].indexOf(marker);
          const expected = subMatches.length === 0 ? 'a' : String.fromCharCode(subMatches[subMatches.length - 1].letter.charCodeAt(0) + 1);
          if (subMatches.length === 0 && letter === 'a') {
            subMatches.push({ letter, marker, index: markerIndex, hasAsterisk: marker.includes('*') });
          } else if (subMatches.length > 0 && letter === expected) {
            subMatches.push({ letter, marker, index: markerIndex, hasAsterisk: marker.includes('*') });
          } else if (subMatches.length > 0 && letter > subMatches[subMatches.length - 1].letter) {
            subMatches.push({ letter, marker, index: markerIndex, hasAsterisk: marker.includes('*') });
          }
        }

        if (subMatches.length >= 2) {
          const stemOnly = cleanStem.slice(0, subMatches[0].index).trim();
          const tfOptions = [];

          // Phân tích đáp án từ Lời giải: "a-sai, b-sai, c-đúng, d-sai" hoặc "a) Đúng b) Sai"
          const explAnswers = {};
          if (explanation) {
            const explMatches = explanation.matchAll(/([a-d])\s*[\-:\=]\s*(đúng|sai|đ|s)\b/gi);
            for (const em of explMatches) {
              explAnswers[em[1].toLowerCase()] = /đ/i.test(em[2]) ? 'Đúng' : 'Sai';
            }
          }

          const hasAnyAsterisk = subMatches.some(s => s.hasAsterisk);

          for (let i = 0; i < subMatches.length; i++) {
            const cur = subMatches[i];
            const next = subMatches[i + 1];
            const startPos = cur.index + cur.marker.length;
            const endPos = next ? next.index : cleanStem.length;
            let stmtText = cleanStem.slice(startPos, endPos).trim();
            stmtText = stmtText.replace(/^[\s*]+/, '').replace(/[\s\.\;]+$/, '').trim();

            let inlineAns = cur.hasAsterisk ? 'Đúng' : (hasAnyAsterisk ? 'Sai' : 'Đúng');

            const ansInStmt = stmtText.match(/(?:[\(\[\{])\s*(Đúng|Sai|Đ|S)\s*(?:[\)\]\}])/i) ||
                              stmtText.match(/(?:Đáp án|ĐA)[\s.:\-–]*(Đúng|Sai|Đ|S)/i);
            if (ansInStmt) {
              inlineAns = /s|sai/i.test(ansInStmt[1]) ? 'Sai' : 'Đúng';
              stmtText = stmtText.replace(ansInStmt[0], '').trim();
            } else if (explAnswers[cur.letter]) {
              inlineAns = explAnswers[cur.letter];
            } else if (answerKeyMap.part2[qNum] && answerKeyMap.part2[qNum][cur.letter]) {
              inlineAns = answerKeyMap.part2[qNum][cur.letter];
            }

            // Replace image tags if any
            if (images && images.length > 0) {
              stmtText = stmtText.replace(/\[Hình\s*(\d+)\]/gi, (match, p1) => {
                const hIdx = parseInt(p1, 10) - 1;
                return (hIdx >= 0 && hIdx < images.length) ? `![Hình ${p1}](${images[hIdx]})` : match;
              });
            }

            tfOptions.push({
              label: cur.letter + ')',
              text: stmtText,
              is_correct: !/sai|false|s/i.test(inlineAns),
              answer: inlineAns
            });
          }

          allQuestions.push({
            id: `q_${globalId++}`,
            content: stemOnly || 'Xét tính đúng-sai của các mệnh đề sau:',
            type: 'Đúng / Sai',
            options: tfOptions,
            subQuestions: tfOptions,
            correctAnswer: tfOptions.map(o => `${o.label} ${o.answer}`).join(', '),
            explanation: explanation,
            imageUrl: imgUrl || ''
          });
          return;
        } else {
          let ans = 'Đúng';
          const ansMatch = block.match(/(?:Đáp án|ĐA)[\s.:\-–]*(Đúng|Sai|Đ|S)/i);
          if (ansMatch) ans = /s|sai/i.test(ansMatch[1]) ? 'Sai' : 'Đúng';
          const cleanQ = block.replace(/^(?:Câu|Bài|Question)\s*\d+[\s.:\-–]*/i, '').trim();
          allQuestions.push({
            id: `q_${globalId++}`,
            content: cleanQ,
            type: 'Đúng / Sai',
            options: ['Đúng', 'Sai'],
            correctAnswer: ans,
            explanation: explanation,
            imageUrl: imgUrl || ''
          });
          return;
        }
      }

      // === DẠNG 2: PHẦN III (Trả lời ngắn chuẩn THPT 2025) ===
      if (blockType === 'SHORT') {
        let cleanQ = block.replace(/^(?:Câu|Bài|Question)\s*\d+[\s.:\-–]*/i, '').trim();
        let ansVal = '';

        // Match real answer markers (exclude rounding instructions like "làm tròn kết quả...")
        const ansMatch = cleanQ.match(/(?:^|\n|;\s*|\.\s*|\(\s*)(?:Đáp án|ĐA|Key|Trả lời)\s*[\:\.\=\-]?\s*([^\n\)]+)/i);
        if (ansMatch) {
          const rawAns = ansMatch[1].trim().replace(/^[\.\_\s\-]+$/g, '').trim();
          if (rawAns && !/làm tròn/i.test(rawAns)) {
            ansVal = rawAns;
            cleanQ = cleanQ.slice(0, ansMatch.index).trim();
          }
        }

        if (!ansVal && answerKeyMap.part3[qNum]) {
          ansVal = answerKeyMap.part3[qNum];
        }

        // Fallback: extract final numeric result from explanation
        if (!ansVal && explanation) {
          const cleanExpl = explanation.replace(/\$/g, " ");
          const explMatches = [...cleanExpl.matchAll(/=\s*([−\-]?[0-9]+(?:\s*[\.,]\s*[0-9]+)?)\s*(?:—–|\.|\n|\)|cm|m|kg|km|\s|$)/gi)];
          if (explMatches.length > 0) {
            ansVal = explMatches[explMatches.length - 1][1].replace(/\s+/g, '');
          } else {
            const explKeyMatch = cleanExpl.match(/(?:Đáp án|Kết quả|Vậy)\s*(?:là)?\s*[\:\.\=\-]?\s*([−\-]?[0-9]+(?:\s*[\.,]\s*[0-9]+)?)/i);
            if (explKeyMatch) {
              ansVal = explKeyMatch[1].replace(/\s+/g, '');
            }
          }
        }

        // Clean trailing open paren or dangling punctuation
        cleanQ = cleanQ.replace(/\(\s*$/, '').trim();

        allQuestions.push({
          id: `q_${globalId++}`,
          content: cleanQ,
          type: 'Trả lời ngắn',
          options: [],
          correctAnswer: ansVal,
          explanation: explanation || (ansVal ? `Kết quả chính xác là: ${ansVal}` : ''),
          imageUrl: imgUrl || ''
        });
        return;
      }

      // === DẠNG 3: PHẦN I (Trắc nghiệm khách quan 4 phương án A, B, C, D) ===
      const optMarkerRegex = /(?:^|[\n\r\t]|\s{2,}|(?<=[\.\;\$\)\]\}])\s+|\b)\s*(\*?\s*([A-D])\s*[\.\)\:\-–]\s*\*?)(?=\s|\$|<|\[|[\w(]|$)/gi;
      const optMatches = [];
      let om;
      while ((om = optMarkerRegex.exec(block)) !== null) {
        const letter = om[2].toUpperCase();
        const marker = om[1];
        const markerIndex = om.index + om[0].indexOf(marker);
        const expected = optMatches.length === 0 ? 'A' : String.fromCharCode(optMatches[optMatches.length - 1].letter.charCodeAt(0) + 1);
        if (optMatches.length === 0 && letter === 'A') {
          optMatches.push({ letter, marker, index: markerIndex, hasAsterisk: marker.includes('*') });
        } else if (optMatches.length > 0 && letter === expected) {
          optMatches.push({ letter, marker, index: markerIndex, hasAsterisk: marker.includes('*') });
        } else if (optMatches.length > 0 && letter > optMatches[optMatches.length - 1].letter) {
          optMatches.push({ letter, marker, index: markerIndex, hasAsterisk: marker.includes('*') });
        }
      }

      let ansLetter = 'A';
      if (optMatches.some(m => m.hasAsterisk)) {
        ansLetter = optMatches.find(m => m.hasAsterisk).letter;
      } else {
        const ansMatch = (block + ' ' + explanation).match(/(?:Chọn|Đáp án|Đáp án đúng|ĐA|Key)[\s.:\-–]*([A-D])\b/i);
        if (ansMatch) ansLetter = ansMatch[1].toUpperCase();
        else if (answerKeyMap.part1[qNum]) ansLetter = answerKeyMap.part1[qNum];
      }

      let cleanQ = block;
      let options = [];

      if (optMatches.length >= 2) {
        cleanQ = block.slice(0, optMatches[0].index).trim();
        cleanQ = cleanQ.replace(/^(?:Câu|Bài|Question)\s*\d+[\s.:\-–]*/i, '').trim();

        for (let i = 0; i < optMatches.length; i++) {
          const cur = optMatches[i];
          const next = optMatches[i + 1];
          const startPos = cur.index + cur.marker.length;
          const endPos = next ? next.index : block.length;
          let optText = block.slice(startPos, endPos).trim();
          optText = optText.replace(/^[\s*]+/, '').replace(/[\s\.\;]+$/, '').trim();

          // Image replacement
          if (images && images.length > 0) {
            optText = optText.replace(/\[Hình\s*(\d+)\]/gi, (match, p1) => {
              const hIdx = parseInt(p1, 10) - 1;
              return (hIdx >= 0 && hIdx < images.length) ? `![Hình ${p1}](${images[hIdx]})` : match;
            });
          }

          options.push(optText);
        }
      } else {
        options = ['Phương án A', 'Phương án B', 'Phương án C', 'Phương án D'];
      }

      allQuestions.push({
        id: `q_${globalId++}`,
        content: cleanQ,
        type: 'Trắc nghiệm khách quan',
        options: options,
        correctAnswer: ansLetter,
        explanation: explanation || `Đáp án đúng là ${ansLetter}.`,
        imageUrl: imgUrl || ''
      });
    });
  });

  return allQuestions.length > 0 ? allQuestions : SAMPLE_MATH_QUESTIONS;
}
